-- State transitions declared for Sms: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION messaging.sms_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."state" IS DISTINCT FROM OLD."state" AND NOT (
           (COALESCE(OLD."state"::text, ''), COALESCE(NEW."state"::text, '')) IN (('outgoing', 'canceled'), ('outgoing', 'process'), ('pending', 'canceled'), ('pending', 'error'), ('pending', 'sent'), ('process', 'canceled'), ('process', 'error'), ('process', 'outgoing'), ('process', 'pending'), ('process', 'sent'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: sms.state % -> %', OLD."state", NEW."state"
            USING ERRCODE = 'check_violation', COLUMN = 'state', CONSTRAINT = 'tg_sms__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS sms_state_transition_check ON messaging.sms;
CREATE TRIGGER sms_state_transition_check
    BEFORE UPDATE OF "state" ON messaging.sms
    FOR EACH ROW EXECUTE FUNCTION messaging.sms_state_transition_check();
